{{ config(materialized='table') }}

    with
    gl_code_combinations as (
    select * from {{ ref("gl_code_combinations") }}
),
fnd_flex_value_sets as (
    select * from {{ ref("fnd_flex_value_sets") }}
),
fnd_id_flex_segments as (
    select * from {{ ref("fnd_id_flex_segments") }}
),
ct_gl_daily_rates_d_stg as (
    SELECT GCC.CODE_COMBINATION_ID AS GLCC_ID, GCC.CHART_OF_ACCOUNTS_ID AS COA_ID, GCC.SEGMENT1 AS SEGMENT1, FFVL_S1.DESCRIPTION AS SEGMENT1_DESC, GCC.SEGMENT1 || '~' || FFVL_S1.DESCRIPTION AS CONCAT_SEGMENT1, GCC.SEGMENT2 AS SEGMENT2, FFVL_S2.DESCRIPTION AS SEGMENT2_DESC, GCC.SEGMENT2 || '~' || FFVL_S2.DESCRIPTION AS CONCAT_SEGMENT2, GCC.SEGMENT3 AS SEGMENT3, FFVL_S3.DESCRIPTION AS SEGMENT3_DESC, GCC.SEGMENT3 || '~' || FFVL_S3.DESCRIPTION AS CONCAT_SEGMENT3, GCC.SEGMENT4 AS SEGMENT4, FFVL_S4.DESCRIPTION AS SEGMENT4_DESC, GCC.SEGMENT4 || '~' || FFVL_S4.DESCRIPTION AS CONCAT_SEGMENT4, GCC.SEGMENT5 AS SEGMENT5, FFVL_S5.DESCRIPTION AS SEGMENT5_DESC, GCC.SEGMENT5 || '~' || FFVL_S5.DESCRIPTION AS CONCAT_SEGMENT5, GCC.SEGMENT6 AS SEGMENT6, FFVL_S6.DESCRIPTION AS SEGMENT6_DESC, GCC.SEGMENT6 || '~' || FFVL_S6.DESCRIPTION AS CONCAT_SEGMENT6, GCC.SEGMENT7 AS SEGMENT7, FFVL_S7.DESCRIPTION AS SEGMENT7_DESC, GCC.SEGMENT7 || '~' || FFVL_S7.DESCRIPTION AS CONCAT_SEGMENT7, GCC.SEGMENT8 AS SEGMENT8, FFVL_S8.DESCRIPTION AS SEGMENT8_DESC, GCC.SEGMENT8 || '~' || FFVL_S8.DESCRIPTION AS CONCAT_SEGMENT8, GCC.SEGMENT9 AS SEGMENT9, FFVL_S9.DESCRIPTION AS SEGMENT9_DESC, GCC.SEGMENT9 || '~' || FFVL_S9.DESCRIPTION AS CONCAT_SEGMENT9, GCC.SEGMENT1 || '.' || GCC.SEGMENT2 || '.' || GCC.SEGMENT3 || '.' || GCC.SEGMENT4 || '.' || GCC.SEGMENT5 || '.' || GCC.SEGMENT6 || '.' || GCC.SEGMENT7 || '.' || GCC.SEGMENT8 || '.' || GCC.SEGMENT9 AS CONCAT_SEGMENT_CODE, FFVL_S1.DESCRIPTION || '~' || FFVL_S2.DESCRIPTION || '~' || FFVL_S3.DESCRIPTION || '~' || FFVL_S4.DESCRIPTION || '~' || FFVL_S5.DESCRIPTION || '~' || FFVL_S6.DESCRIPTION || '~' || FFVL_S7.DESCRIPTION || '~' || FFVL_S8.DESCRIPTION || '~' || FFVL_S9.DESCRIPTION AS CONCAT_SEGMENT_DESC, GCC.ACCOUNT_TYPE, GCC.ENABLED_FLAG, GCC.SUMMARY_FLAG, GCC.START_DATE_ACTIVE AS START_DT_ACTIVE, GCC.END_DATE_ACTIVE AS END_DT_ACTIVE, GCC.LAST_UPDATE_DATE AS CREATION_DT, GCC.LAST_UPDATE_DATE AS LAST_UPDATE_DT, GCC.LAST_UPDATED_BY AS CREATED_BY, GCC.LAST_UPDATED_BY, CAST(GCC.CODE_COMBINATION_ID AS VARCHAR) AS INTEGRATION_ID, 1000 AS DATASOURCE_NUM_ID, GCC.DETAIL_POSTING_ALLOWED_FLAG, GCC.DETAIL_BUDGETING_ALLOWED_FLAG FROM gl_code_combinations GCC LEFT JOIN ( FND_FLEX_VALUES_VL FFVL_S1 INNER JOIN fnd_flex_value_sets FFVS_S1 ON ( FFVS_S1.FLEX_VALUE_SET_ID = FFVL_S1.FLEX_VALUE_SET_ID ) INNER JOIN fnd_id_flex_segments FIFS_S1 ON ( FIFS_S1.FLEX_VALUE_SET_ID = FFVL_S1.FLEX_VALUE_SET_ID AND FIFS_S1.SEGMENT_NUM = 1 AND FIFS_S1.ID_FLEX_CODE = 'GL#' ) ) ON ( FIFS_S1.ID_FLEX_NUM = GCC.CHART_OF_ACCOUNTS_ID AND GCC.SEGMENT1 = FFVL_S1.FLEX_VALUE ) LEFT JOIN ( FND_FLEX_VALUES_VL FFVL_S2 INNER JOIN fnd_flex_value_sets FFVS_S2 ON ( FFVS_S2.FLEX_VALUE_SET_ID = FFVL_S2.FLEX_VALUE_SET_ID ) INNER JOIN fnd_id_flex_segments FIFS_S2 ON ( FIFS_S2.FLEX_VALUE_SET_ID = FFVL_S2.FLEX_VALUE_SET_ID AND FIFS_S2.SEGMENT_NUM = 2 AND FIFS_S2.ID_FLEX_CODE = 'GL#' ) ) ON ( FIFS_S2.ID_FLEX_NUM = GCC.CHART_OF_ACCOUNTS_ID AND GCC.SEGMENT2 = FFVL_S2.FLEX_VALUE ) LEFT JOIN ( FND_FLEX_VALUES_VL FFVL_S3 INNER JOIN fnd_flex_value_sets FFVS_S3 ON ( FFVS_S3.FLEX_VALUE_SET_ID = FFVL_S3.FLEX_VALUE_SET_ID ) INNER JOIN fnd_id_flex_segments FIFS_S3 ON ( FIFS_S3.FLEX_VALUE_SET_ID = FFVL_S3.FLEX_VALUE_SET_ID AND FIFS_S3.SEGMENT_NUM = 3 AND FIFS_S3.ID_FLEX_CODE = 'GL#' ) ) ON ( FIFS_S3.ID_FLEX_NUM = GCC.CHART_OF_ACCOUNTS_ID AND GCC.SEGMENT3 = FFVL_S3.FLEX_VALUE ) LEFT JOIN ( FND_FLEX_VALUES_VL FFVL_S4 INNER JOIN fnd_flex_value_sets FFVS_S4 ON ( FFVS_S4.FLEX_VALUE_SET_ID = FFVL_S4.FLEX_VALUE_SET_ID ) INNER JOIN fnd_id_flex_segments FIFS_S4 ON ( FIFS_S4.FLEX_VALUE_SET_ID = FFVL_S4.FLEX_VALUE_SET_ID AND FIFS_S4.SEGMENT_NUM = 4 AND FIFS_S4.ID_FLEX_CODE = 'GL#' ) ) ON ( FIFS_S4.ID_FLEX_NUM = GCC.CHART_OF_ACCOUNTS_ID AND GCC.SEGMENT4 = FFVL_S4.FLEX_VALUE ) LEFT JOIN ( FND_FLEX_VALUES_VL FFVL_S5 INNER JOIN fnd_flex_value_sets FFVS_S5 ON ( FFVS_S5.FLEX_VALUE_SET_ID = FFVL_S5.FLEX_VALUE_SET_ID ) INNER JOIN fnd_id_flex_segments FIFS_S5 ON ( FIFS_S5.FLEX_VALUE_SET_ID = FFVL_S5.FLEX_VALUE_SET_ID AND FIFS_S5.SEGMENT_NUM = 5 AND FIFS_S5.ID_FLEX_CODE = 'GL#' ) ) ON ( FIFS_S5.ID_FLEX_NUM = GCC.CHART_OF_ACCOUNTS_ID AND GCC.SEGMENT5 = FFVL_S5.FLEX_VALUE ) LEFT JOIN ( FND_FLEX_VALUES_VL FFVL_S6 INNER JOIN fnd_flex_value_sets FFVS_S6 ON ( FFVS_S6.FLEX_VALUE_SET_ID = FFVL_S6.FLEX_VALUE_SET_ID ) INNER JOIN fnd_id_flex_segments FIFS_S6 ON ( FIFS_S6.FLEX_VALUE_SET_ID = FFVL_S6.FLEX_VALUE_SET_ID AND FIFS_S6.SEGMENT_NUM = 6 AND FIFS_S6.ID_FLEX_CODE = 'GL#' ) ) ON ( FIFS_S6.ID_FLEX_NUM = GCC.CHART_OF_ACCOUNTS_ID AND GCC.SEGMENT6 = FFVL_S6.FLEX_VALUE ) LEFT JOIN ( FND_FLEX_VALUES_VL FFVL_S7 INNER JOIN fnd_flex_value_sets FFVS_S7 ON ( FFVS_S7.FLEX_VALUE_SET_ID = FFVL_S7.FLEX_VALUE_SET_ID ) INNER JOIN fnd_id_flex_segments FIFS_S7 ON ( FIFS_S7.FLEX_VALUE_SET_ID = FFVL_S7.FLEX_VALUE_SET_ID AND FIFS_S7.SEGMENT_NUM = 7 AND FIFS_S7.ID_FLEX_CODE = 'GL#' ) ) ON ( FIFS_S7.ID_FLEX_NUM = GCC.CHART_OF_ACCOUNTS_ID AND GCC.SEGMENT7 = FFVL_S7.FLEX_VALUE ) LEFT JOIN ( FND_FLEX_VALUES_VL FFVL_S8 INNER JOIN fnd_flex_value_sets FFVS_S8 ON ( FFVS_S8.FLEX_VALUE_SET_ID = FFVL_S8.FLEX_VALUE_SET_ID ) INNER JOIN fnd_id_flex_segments FIFS_S8 ON ( FIFS_S8.FLEX_VALUE_SET_ID = FFVL_S8.FLEX_VALUE_SET_ID AND FIFS_S8.SEGMENT_NUM = 8 AND FIFS_S8.ID_FLEX_CODE = 'GL#' ) ) ON ( FIFS_S8.ID_FLEX_NUM = GCC.CHART_OF_ACCOUNTS_ID AND GCC.SEGMENT8 = FFVL_S8.FLEX_VALUE ) LEFT JOIN ( FND_FLEX_VALUES_VL FFVL_S9 INNER JOIN fnd_flex_value_sets FFVS_S9 ON ( FFVS_S9.FLEX_VALUE_SET_ID = FFVL_S9.FLEX_VALUE_SET_ID ) INNER JOIN fnd_id_flex_segments FIFS_S9 ON ( FIFS_S9.FLEX_VALUE_SET_ID = FFVL_S9.FLEX_VALUE_SET_ID AND FIFS_S9.SEGMENT_NUM = 9 AND FIFS_S9.ID_FLEX_CODE = 'GL#' ) ) ON ( FIFS_S9.ID_FLEX_NUM = GCC.CHART_OF_ACCOUNTS_ID AND GCC.SEGMENT9 = FFVL_S9.FLEX_VALUE )
)
    select * from ct_gl_daily_rates_d_stg;
